# Uniform camera-scale actual app crops, no changes to app pixels.
def sheet(images,labels,out,box=None):
    ims=[Image.open(p).convert('RGB') for p in images]
    if box:ims=[im.crop(box) for im in ims]
    w,h=ims[0].size;assert all(im.size==(w,h) for im in ims)
    canvas=Image.new('RGB',(w*len(ims)+24*(len(ims)+1),h+96),(17,20,23));draw=ImageDraw.Draw(canvas)
    for i,(im,label) in enumerate(zip(ims,labels)):
        x=24+i*(w+24);canvas.paste(im,(x,72));draw.text((x,23),label,font=font,fill=(229,231,233))
    canvas.save(out)
